k = col1.replace('$', '').replace(',', '')\n            issue_date = col2\n            \n            if amount_13wk.isdigit():\n                bill_data.append({\n                    'amount_13wk': int(amount_13wk),\n                    'amount_26wk': int(amount_26wk),\n                    'issue_date': issue_date\n                })\n\nprint(\"\\nBill data from 1972:\")\nfor b in bill_data:\n    print(f\"  {b['issue_date']}: 13wk=${b['amount_13wk']}M, 26wk=${b['amount_26wk']}M\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
